from typing import List

class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        result = set()
        n = len(nums)
        for i in range(n - 2):
            seen = set()
            for j in range(i + 1, n):
                need = -nums[i] - nums[j]
                if need in seen:
                    result.add((nums[i], need, nums[j]))
                seen.add(nums[j])
        return [list(triplet) for triplet in sorted(result)]

